{
 "command": "git ls-files && cat README* 2>/dev/null | head -50",
 "description": "List repo files and README"
}

{
 "mode": "filter",
 "query": "invoice retention purge",
 "include_invalidated": true
}

{
 "command": "cat migrations/*.sql && cat scripts/backfill_tax.py scripts/export.py docs/ops/backfills.md && grep -n -i -A5 \"retention\\|purge\\|delete\" docs/runbook.md docs/*.md; cat pyproject.toml",
 "description": "Read schema, sibling scripts, and docs"
}

{
 "command": "cat src/billing/refunds.py src/billing/invoices.py tests/test_db.py docker-compose.yml; grep -rn \"psycopg\\|DATABASE_URL\\|structlog\" --include=*.py . | head -20",
 "description": "Read refunds, invoices, DB test code"
}

{
 "command": "python -m py_compile scripts/purge_invoices.py && python scripts/purge_invoices.py; echo rc=$?; python scripts/purge_invoices.py --batch-size 2000; echo rc=$?; python -c \"import psycopg\" 2>&1 | tail -1",
 "description": "Compile and smoke-test argument handling"
}
